/**
 * Builds the social card PNG (1200×630) from assets/social-card.svg.
 *
 * assets/social-card.svg is generated by scripts/build-social-card.py, which
 * converts the IBM Plex Mono wordmark into vector paths. That matters: sharp
 * renders SVG through librsvg, which resolves fonts via the *system* font list
 * and cannot read our self-hosted .woff2. Any <text> element referencing
 * "IBM Plex Mono" would silently fall back to Courier on machines without Plex
 * installed — including CI. Paths have no such dependency.
 *
 * Run: npm run build-social-card  (regenerates the SVG, then rasterises it)
 */
const path = require('path');
const sharp = require('sharp');

const root = path.join(__dirname, '..');
const assets = path.join(root, 'assets');

const input = path.join(assets, 'social-card.svg');
const output = path.join(assets, 'social-card.png');

sharp(input)
  .resize(1200, 630)
  .png({ compressionLevel: 9, palette: true })
  .toFile(output)
  .then((info) => {
    const kb = (info.size / 1024).toFixed(1);
    console.log('Created assets/social-card.png (1200×630, ' + kb + ' KB)');
  })
  .catch((err) => {
    console.error(err);
    process.exit(1);
  });
